package space.glidetv.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
final class RamDialog {
 final Activity activity;final Runnable releaseCache;final Map<String,Drawable> knownIcons;final java.util.function.Function<String,String> names;final Handler ui=new Handler(Looper.getMainLooper());final ExecutorService executor=Executors.newSingleThreadExecutor();
 final LinearLayout root,processRows;final TextView used,total,available,health,cache,status;final TextView clearButton,refreshButton;final AlertDialog dialog;boolean closed;
 int dp(int v){return Math.round(v*activity.getResources().getDisplayMetrics().density);}LinearLayout row(){LinearLayout l=new LinearLayout(activity);l.setGravity(Gravity.CENTER_VERTICAL);return l;}LinearLayout col(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);return l;}
 TextView label(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setIncludeFontPadding(false);return t;}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 void gap(LinearLayout l,int h){l.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(h)));}
 TextView stat(LinearLayout row,String name,int color){LinearLayout card=col();card.setPadding(dp(15),dp(9),dp(15),dp(9));card.setBackground(shape(0xff213448,13));card.addView(label(name,10,0xffb9cde0));gap(card,6);TextView value=label("—",23,color);card.addView(value);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(61),1);p.setMarginEnd(dp(8));row.addView(card,p);return value;}
 TextView button(String name,Runnable action,boolean primary){TextView t=label(name,13,0xffe8f4ff);t.setGravity(Gravity.CENTER);t.setPadding(dp(20),0,dp(20),0);t.setFocusable(true);t.setClickable(true);t.setBackground(shape(primary?0xff345d69:0xff24394d,14));t.setOnFocusChangeListener((v,f)->{v.setBackground(shape(f?0xff4d7585:primary?0xff345d69:0xff24394d,14));v.setScaleX(f?1.025f:1);v.setScaleY(f?1.025f:1);});t.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(35));p.setMarginStart(dp(8));t.setLayoutParams(p);return t;}
 RamDialog(Activity a,Runnable clear,Map<String,Drawable> icons,java.util.function.Function<String,String> resolver){activity=a;releaseCache=clear;knownIcons=icons;names=resolver;root=col();root.setPadding(dp(24),dp(20),dp(24),dp(18));GradientDrawable bg=shape(0xff142436,24);bg.setStroke(dp(1),0xff40576d);root.setBackground(bg);
 LinearLayout heading=row();heading.addView(label("Memory",25,Color.WHITE),new LinearLayout.LayoutParams(0,-2,1));health=label("",11,0xffb8e2c6);heading.addView(health);root.addView(heading);gap(root,7);root.addView(label("Android, TV services and recently used apps share this memory.",11,0xffb1c5d8));gap(root,13);
 LinearLayout cards=row();total=stat(cards,"TOTAL RAM",0xffeaf3ff);used=stat(cards,"IN USE",0xffbdd8f4);available=stat(cards,"AVAILABLE",0xffb9e8cd);root.addView(cards);gap(root,15);
 LinearLayout title=row();title.addView(label("Largest processes",14,Color.WHITE),new LinearLayout.LayoutParams(0,-2,1));title.addView(label("MEMORY SHARE",9,0xff9fb9d1));root.addView(title);gap(root,6);
 ScrollView list=new ScrollView(a);list.setVerticalScrollBarEnabled(false);processRows=col();list.addView(processRows);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));gap(root,7);
 cache=label("",10,0xffa8c0d8);cache.setMaxLines(2);root.addView(cache);gap(root,5);status=label("Reading memory…",11,0xffc6dbec);status.setMaxLines(2);root.addView(status,new LinearLayout.LayoutParams(-1,dp(31)));gap(root,7);
 LinearLayout actions=row();actions.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));refreshButton=button("Refresh",()->refresh(),false);actions.addView(refreshButton);actions.addView(button("Close",()->close(),false));clearButton=button("Clear RAM",()->clear(),true);actions.addView(clearButton);root.addView(actions);
 dialog=new AlertDialog.Builder(a).setView(root).create();dialog.setOnDismissListener(d->{closed=true;executor.shutdownNow();ui.removeCallbacksAndMessages(null);processRows.removeAllViews();});dialog.show();dialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setLayout(dp(760),dp(470));android.view.ViewGroup.LayoutParams rootSize=root.getLayoutParams();rootSize.height=dp(430);root.setLayoutParams(rootSize);local();refresh();}
 void close(){dialog.dismiss();}
 ActivityManager.MemoryInfo info(){ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)activity.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(m);return m;}
 String mb(long kb){return String.format(Locale.US,"%.0f MB",kb/1024d);}String gb(long bytes){return String.format(Locale.US,"%.2f GB",bytes/1073741824d);}
 void local(){ActivityManager.MemoryInfo m=info();total.setText(gb(m.totalMem));used.setText(gb(m.totalMem-m.availMem));available.setText(gb(m.availMem));health.setText(m.lowMemory?"LOW MEMORY":(100*(m.totalMem-m.availMem)/m.totalMem)+"% IN USE · NORMAL");}
 static synchronized String token(Context c)throws Exception{return MemoryHelperClient.token(c);}
 JSONObject request(String op)throws Exception{return MemoryHelperClient.request(activity,op);}
 void busy(boolean b){clearButton.setEnabled(!b);refreshButton.setEnabled(!b);clearButton.setAlpha(b?.45f:1);refreshButton.setAlpha(b?.45f:1);}
 void refresh(){busy(true);local();status.setText("Reading TV memory…");executor.execute(()->{try{JSONObject r=request("snapshot");ui.post(()->{if(closed)return;render(r);busy(false);status.setText("Available RAM includes reclaimable memory. App shares are a current snapshot.");});}catch(Exception e){android.util.Log.w("GlideRam","Snapshot unavailable",e);ui.post(()->{if(closed)return;local();busy(false);processRows.removeAllViews();Debug.MemoryInfo own=new Debug.MemoryInfo();Debug.getMemoryInfo(own);addProcess("space.glidetv.launcher",own.getTotalPss(),own.getTotalPss());status.setText("TV-wide details need the debugging helper. Restart it after a TV reboot.");});}});}
 void addProcess(String name,long kb,long largest){String title=names.apply(name);Drawable icon=knownIcons.get(name.split(":")[0]);if(icon==null)icon=activity.getDrawable(android.R.drawable.sym_def_app_icon);if(name.equals("system"))title="Android system";if(name.equals("app_process"))title="RAM control helper";LinearLayout line=row();line.setPadding(dp(7),dp(5),dp(7),dp(5));ImageView image=new ImageView(activity);image.setImageDrawable(icon);image.setScaleType(ImageView.ScaleType.FIT_CENTER);line.addView(image,new LinearLayout.LayoutParams(dp(27),dp(27)));LinearLayout names=col();TextView text=label(title,12,0xffe7f0fc);text.setSingleLine(true);text.setEllipsize(android.text.TextUtils.TruncateAt.END);names.addView(text);gap(names,4);ProgressBar bar=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)Math.min(1000,1000*kb/Math.max(1,largest)));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff92b9d7));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0x203b5368));names.addView(bar,new LinearLayout.LayoutParams(-1,dp(2)));LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);np.setMarginStart(dp(12));np.setMarginEnd(dp(18));line.addView(names,np);line.addView(label(mb(kb),12,0xffcce0f1));processRows.addView(line,new LinearLayout.LayoutParams(-1,dp(39)));String pkg=name.split(":")[0];if(canStop(pkg)){final String appTitle=title;line.setFocusable(true);line.setClickable(true);line.setContentDescription(appTitle+", "+mb(kb)+". Select to stop app.");line.setOnFocusChangeListener((v,f)->v.setBackground(f?shape(0xff2c465b,10):null));line.setOnClickListener(v->stopSheet(pkg,appTitle));}}
 boolean canStop(String pkg){if(pkg.equals(activity.getPackageName())||pkg.equals("android")||pkg.startsWith("com.android.")||pkg.startsWith("com.tcl.")||pkg.startsWith("com.mediatek.")||pkg.equals("com.google.android.gms")||pkg.equals("com.google.android.gsf")||pkg.equals("com.google.android.katniss")||pkg.equals("com.google.android.tv.remote.service"))return false;return activity.getPackageManager().getLeanbackLaunchIntentForPackage(pkg)!=null||activity.getPackageManager().getLaunchIntentForPackage(pkg)!=null;}
 void stopSheet(String pkg,String name){LinearLayout panel=col();panel.setPadding(dp(24),dp(20),dp(24),dp(20));panel.setBackground(shape(0xff1c3044,22));panel.addView(label("Stop "+name+"?",23,Color.WHITE));gap(panel,12);TextView description=label("Stops this app and its playback. Saved app data stays on your TV.",12,0xffc3d7e9);panel.addView(description);gap(panel,20);LinearLayout buttons=row();buttons.addView(new View(activity),new LinearLayout.LayoutParams(0,1,1));final AlertDialog[] sheet=new AlertDialog[1];buttons.addView(button("Cancel",()->sheet[0].dismiss(),false));buttons.addView(button("Stop app",()->{sheet[0].dismiss();stopApp(pkg);},true));panel.addView(buttons);sheet[0]=new AlertDialog.Builder(activity).setView(panel).create();sheet[0].show();sheet[0].getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));sheet[0].getWindow().setLayout(dp(520),-2);}
 void stopApp(String pkg){busy(true);status.setText("Stopping app… Saved data is preserved.");executor.execute(()->{try{JSONObject result=request("stop:"+pkg);ui.post(()->{if(closed)return;render(result);status.setText("App stopped. Select its Home icon whenever you want to open it again.");busy(false);});}catch(Exception e){android.util.Log.w("GlideRam","Stop unavailable",e);ui.post(()->{if(closed)return;status.setText("Could not stop this app. Check the debugging helper connection.");busy(false);});}});}
 void render(JSONObject r){local();processRows.removeAllViews();JSONArray entries=r.optJSONArray("processes");long largest=entries!=null&&entries.length()>0?entries.optJSONObject(0).optLong("kb"):1;if(entries!=null)for(int n=0;n<entries.length();n++){JSONObject p=entries.optJSONObject(n);addProcess(p.optString("name"),p.optLong("kb"),largest);}long cached=Math.max(0,r.optLong("Cached")+r.optLong("Buffers")+r.optLong("SReclaimable")-r.optLong("Shmem"));cache.setText("Unused "+mb(r.optLong("MemFree"))+"  ·  Reclaimable file cache "+mb(cached)+"  ·  Swap "+mb(r.optLong("SwapTotal")-r.optLong("SwapFree"))+"\nCache overlaps available RAM. Process shares include shared-memory accounting.");}
 void clear(){long before=info().availMem;releaseCache.run();busy(true);status.setText("Releasing cached apps. Active services and app data are preserved.");executor.execute(()->{try{JSONObject r=request("clear");ui.post(()->{if(closed)return;render(r);long gain=info().availMem-before;status.setText(gain>0?"Cleanup finished · "+mb(gain/1024)+" more RAM available. Android may reuse it.":"Cleanup finished · "+gb(info().availMem)+" available. Active services remain running.");busy(false);});}catch(Exception e){android.util.Log.w("GlideRam","Cleanup helper unavailable",e);ui.post(()->{if(closed)return;local();status.setText("Glide cache released. Reconnect the debugging helper for TV-wide cleanup.");busy(false);});}});}
}
